use std::{
    ffi::{OsStr, OsString},
    path::Path,
};

use anyhow::{Context, Result};

use crate::{local_refs::Rewriter, shared::SyncWorkflow, sync_entry::SyncEntry};

/// Marks a workflow as generated by this tool, so orphans can be identified in targets.
pub const MARKER_PREFIX: &str = "# synced from apix-actions/.github/workflows/";

/// Prepare the workflow files in `directory` that carry at least one valid sync header.
pub fn scan(directory: &Path, rewriter: &Rewriter) -> Result<Vec<SyncWorkflow>> {
    let mut workflows = Vec::new();
    for (file_name, contents) in workflow_files(directory, rewriter)? {
        let label = file_name.to_string_lossy().into_owned();
        let workflow = parse_workflow(file_name, &contents, rewriter)
            .with_context(|| format!("preparing workflow {label}"))?;
        if !workflow.sync.is_empty() {
            workflows.push(workflow);
        }
    }

    Ok(workflows)
}

/// Read the `.yaml`/`.yml` files in `directory` at the release commit, as `(name, contents)`.
fn workflow_files(directory: &Path, rewriter: &Rewriter) -> Result<Vec<(OsString, String)>> {
    let tag = &rewriter.release().tag;
    let repository = rewriter.repository()?;
    let commit = rewriter.release_commit(&repository)?;
    let entry = commit
        .tree()
        .context("reading the release tree")?
        .get_path(directory)
        .with_context(|| format!("reading {} at release {tag}", directory.display()))?;
    let tree = repository
        .find_tree(entry.id())
        .with_context(|| format!("reading {} at release {tag}", directory.display()))?;

    let mut files = Vec::new();
    for entry in tree.iter() {
        let Ok(name) = entry.name() else {
            continue;
        };
        if !matches!(
            Path::new(name).extension().and_then(OsStr::to_str),
            Some("yaml" | "yml")
        ) {
            continue;
        }

        let blob = repository
            .find_blob(entry.id())
            .with_context(|| format!("reading {name} at release {tag}"))?;
        let contents = std::str::from_utf8(blob.content())
            .with_context(|| format!("{name} at release {tag} is not UTF-8"))?;
        files.push((OsString::from(name), contents.to_string()));
    }

    Ok(files)
}

// Remove sync metadata and retain the workflow body for target repositories.
fn parse_workflow(
    file_name: OsString,
    contents: &str,
    rewriter: &Rewriter,
) -> Result<SyncWorkflow> {
    // Sync headers are metadata for this tool, not valid workflow configuration.
    let mut sync = Vec::new();
    let filtered_lines: Vec<_> = contents
        .lines()
        .filter(|line| match line.parse::<SyncEntry>() {
            Ok(entry) => {
                sync.push(entry.repo);
                false
            }
            Err(_) => true,
        })
        .collect();

    let contents = filtered_lines.join("\n").trim().to_string();
    let contents = if sync.is_empty() {
        // Not a sync source, so its references stay local to this repository.
        contents
    } else {
        // Local references only resolve here; targets need a permalink to this repository.
        let contents = rewriter.rewrite(&contents)?;
        format!("{MARKER_PREFIX}{}\n{contents}", file_name.to_string_lossy())
    };

    Ok(SyncWorkflow {
        file_name,
        sync,
        contents,
    })
}

#[cfg(test)]
mod tests {
    use std::{
        ffi::OsString,
        fs,
        path::{Path, PathBuf},
        time::SystemTime,
    };

    use git2::{Repository, Signature};
    use non_empty_string::NonEmptyString;

    use super::parse_workflow;
    use crate::{
        local_refs::{ReleaseRef, Rewriter},
        shared::Repo,
    };

    // Rewriting is covered in `local_refs`; these cases carry no local references.
    fn rewriter() -> Rewriter {
        let source = Repo::new(
            NonEmptyString::new("mongodb".to_string()).expect("non-empty owner"),
            NonEmptyString::new("apix-action".to_string()).expect("non-empty name"),
        );

        Rewriter::new(
            source,
            std::env::temp_dir(),
            ReleaseRef {
                sha: "abc123".to_string(),
                tag: "v18".to_string(),
            },
        )
    }

    // A checkout whose `.github/workflows` holds `files`, committed and tagged `v18`.
    fn release_root(label: &str, files: &[(&str, &str)]) -> (PathBuf, Rewriter) {
        let unique = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .expect("clock after epoch")
            .as_nanos();
        let root =
            std::env::temp_dir().join(format!("apix-scan-{label}-{}-{unique}", std::process::id()));
        let workflows = root.join(".github/workflows");
        fs::create_dir_all(&workflows).expect("create workflow directory");
        for (name, contents) in files {
            fs::write(workflows.join(name), contents).expect("write workflow");
        }

        let repository = Repository::init(&root).expect("init repository");
        let mut index = repository.index().expect("open index");
        index
            .add_all(["*"], git2::IndexAddOption::DEFAULT, None)
            .expect("stage files");
        index.write().expect("write index");
        let tree = repository
            .find_tree(index.write_tree().expect("write tree"))
            .expect("read tree");
        let signature = Signature::now("test", "test@example.com").expect("signature");
        let commit = repository
            .commit(Some("HEAD"), &signature, &signature, "init", &tree, &[])
            .expect("commit");
        repository
            .reference("refs/tags/v18", commit, false, "add tag")
            .expect("tag");

        let source = Repo::new(
            NonEmptyString::new("mongodb".to_string()).expect("non-empty owner"),
            NonEmptyString::new("apix-action".to_string()).expect("non-empty name"),
        );
        let rewriter = Rewriter::new(
            source,
            root.clone(),
            ReleaseRef {
                sha: commit.to_string(),
                tag: "v18".to_string(),
            },
        );
        (root, rewriter)
    }

    #[test]
    fn scan_reads_the_workflows_at_the_release_not_the_checkout() {
        let (root, rewriter) =
            release_root("release-tree", &[("kept.yaml", "# sync -> mongodb/x\n")]);
        // Written after the tag, so absent from the release.
        fs::write(
            root.join(".github/workflows/_new.yaml"),
            "# sync -> mongodb/x\n",
        )
        .expect("write workflow");

        let scanned = super::scan(Path::new(".github/workflows"), &rewriter).expect("scan");

        assert_eq!(
            scanned
                .iter()
                .map(|workflow| workflow.file_name.clone())
                .collect::<Vec<_>>(),
            vec![OsString::from("kept.yaml")]
        );

        fs::remove_dir_all(root).expect("clean up");
    }

    #[test]
    fn parse_workflow_removes_valid_sync_headers() {
        let contents = "name: test\n# sync -> mongodb/first\n# sync -> mongodb/second\njobs:\n";

        let workflow =
            parse_workflow("test.yaml".into(), contents, &rewriter()).expect("valid workflow");

        assert_eq!(workflow.file_name, "test.yaml");
        assert_eq!(workflow.sync.len(), 2);
        assert_eq!(
            workflow.sync[0].owner,
            NonEmptyString::new("mongodb".to_string()).unwrap()
        );
        assert_eq!(
            workflow.sync[0].repository,
            NonEmptyString::new("first".to_string()).unwrap()
        );
        assert_eq!(
            workflow.contents,
            "# synced from apix-actions/.github/workflows/test.yaml\nname: test\njobs:"
        );
    }

    #[test]
    fn parse_workflow_keeps_invalid_sync_headers() {
        let contents = "# sync -> invalid\n# not a sync header\n";

        let workflow =
            parse_workflow("test.yaml".into(), contents, &rewriter()).expect("valid workflow");

        assert!(workflow.sync.is_empty());
        assert_eq!(workflow.contents, contents.trim());
    }

    #[test]
    fn parse_workflow_adds_comment_when_contents_are_empty() {
        let workflow = parse_workflow("test.yaml".into(), "# sync -> mongodb/test\n", &rewriter())
            .expect("valid workflow");

        assert_eq!(
            workflow.contents,
            "# synced from apix-actions/.github/workflows/test.yaml\n"
        );
    }
}
